            delta,
            z,
            pack_progress_reference(reference_i, escaped, glitched),
            i,
            saved.epoch,
            escape_magnitude,
        )
    }
}

pub fn resolve_prefix_step(
    _ reference_i: u32,
    _ iteration: u32,
    _ max_iter: u32,
    _ valid_samples: u32,
    _ prefix_only: bool,
) -> PrefixIndices {
    let prefix_limit: u32 = if valid_samples > 0 {
        valid_samples - 1
    } else {
        0
    }
    let step_limit: u32 = if prefix_only && prefix_limit < max_iter {
        prefix_limit
    } else {
        max_iter
