    WebGpuBackend,
}
use std::web::view::{Extent, Surface, SurfaceEvent}
use algebra::Vec2
use fmath::{PixelSample, abs, from_i32, to_i32, max, min}
use precision::fixed::{
    mandelbrot_advance8,
    to_f32_quad_bits,
    fixed_magnitude_from_words,
    fixed_magnitude_to_words,
}

extern {
    const fn __bitcast<From, To>(_: From) -> To
}

use ingot::policy::{
    Camera,
    MandelbrotParams,
    MandelbrotViewState,
    SurfaceStateEnvelope,
    SharpBacking,
    mandelbrot_params,
    initial_state,
    transition,
    iteration_limit,
    progress,
    preview_budget,
    sharpness,
}
use ingot::orbit::{
    Complex,
    OrbitProgress,
    PackedReference,
    PrefixIndices,
    ReferenceReal,
    ReferenceStep,
    clear_reference_checkpoint,
    continue_pixel,
    continue_preview_pixel,
    empty_progress,
    load_reference_checkpoint,
    pack_progress_reference,
    progress_color,
    progress_has_outcome,
    progress_is_escaped,
    progress_is_glitched,
    progress_is_presentable,
    progress_is_terminal,
    progress_outcome_flags,
    progress_reference_index,
    progress_with_presentable,
    pack_progress_reference,
    reference_center,
    reference_step,
    resolve_prefix_step,
    sample_pixel,
    store_reference_checkpoint,
    INVALID_REFERENCE,
    ORBIT_CAPACITY,
    ORBIT_CENTER_INDEX,
    ORBIT_META_INDEX,
}
use ingot::palette::interior
use ingot::partition::{
    CohortPixel,
    Pixel,
    RefinementSchedule,
    order_block,
    unpack_order_byte,
    seed_pixel,
}
use ingot::image::{
    BilinearTap,
    Color,
    unpack_lab,
    pack_lab,
    display_rgba,
